mapper.select:
SELECT d.id, d.category_id, c.name AS category_name, d.name, d.description, d.image_url, d.price, d.sort, d.status, d.create_time, d.update_time FROM dish d JOIN category c ON c.id = d.category_id WHERE d.status = 1
AND d.category_id = #{categoryId}
ORDER BY c.sort ASC, d.sort ASC, d.id ASC
